            ["1baef474-8737-402b-aa5a-3b91cba4d736"],
        ],
        description="list of UUIDs of subscribed users",
    )

    @model_validator(mode="before")
    def check_if_values_specified(v):
        if (v.get("entity_uuid") or v.get("entity_partition")) and not (
            v.get("entity_uuid") and v.get("entity_partition")
        ):
            if not v.get("entity_uuid"):
                raise HTTPException(status_code=422, detail="entity_partition must be sent with entity_uuid")
